CREATE USER superatom IDENTIFIED BY "Choose-a-password-1";
GRANT CREATE SESSION TO superatom;
GRANT SELECT ANY TABLE TO superatom;

CREATE ROLE superatom LOGIN PASSWORD 'choose-a-password';
GRANT CONNECT ON DATABASE your_database TO superatom;
GRANT USAGE ON SCHEMA public TO superatom;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO superatom;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO superatom;

CREATE LOGIN superatom WITH PASSWORD = 'Choose-a-password-1';
USE your_database;
CREATE USER superatom FOR LOGIN superatom;
ALTER ROLE db_datareader ADD MEMBER superatom;
